class Denied extends Error { constructor(message, status=401) { super(message); this.status=status; } }
const json = (body, status=200) => new Response(JSON.stringify(body), {status,headers:{...headers,'Content-Type':'application/json; charset=utf-8'}});
function hex(s) { if(!/^[a-f0-9]{64}$/i.test(s||'')) throw new Denied('Кабинет ещё настраивается',503); return Uint8Array.from(s.match(/../g),x=>parseInt(x,16)); }
function unbase(s) { if(!/^[\w-]+$/.test(s||'')) throw new Denied('Откройте кабинет заново через бота'); return Uint8Array.from(atob(s.replace(/-/g,'+').replace(/_/g,'/')+'='.repeat((4-s.length%4)%4)),x=>x.charCodeAt(0)); }
async function verify(key, bytes, data) { const k=await crypto.subtle.importKey('raw',hex(key),{name:'HMAC',hash:'SHA-256'},false,['verify']); return crypto.subtle.verify('HMAC',k,bytes,enc.encode(data)); }
export async function authorize(body, env, now=Math.floor(Date.now()/1000)) {
  if(env.BROWSER_IDENTITY&&!body.ticket&&!body.initData)return env.BROWSER_IDENTITY;
  if(typeof body.ticket!=='string' || body.ticket.length>2048 || typeof body.initData!=='string' || body.initData.length>16384) throw new Denied('Откройте кабинет кнопкой в Telegram-боте');
  const parts=body.ticket.split('.'); if(parts.length!==2 || !await verify(env.CABINET_SIGNING_KEY,unbase(parts[1]),parts[0])) throw new Denied('Откройте кабинет заново через бота');
  const ticket=JSON.parse(new TextDecoder().decode(unbase(parts[0])));
  if(ticket.v!==1 || !Number.isSafeInteger(ticket.uid) || ticket.uid<=0 || !/^\d+$/.test(String(ticket.employee_id)) || !Number.isSafeInteger(ticket.iat) || !Number.isSafeInteger(ticket.exp) || ticket.iat>now+30 || ticket.exp<=now || ticket.exp-ticket.iat>3600 || now-ticket.iat>3600) throw new Denied('Ссылка устарела. Нажмите «Личный кабинет» в боте ещё раз');
  const p=new URLSearchParams(body.initData); const fields=[...p];
  if(new Set(fields.map(x=>x[0])).size!==fields.length) throw new Denied('Не удалось проверить вход через Telegram');
  const hash=p.get('hash'); if(!/^[a-f0-9]{64}$/i.test(hash||'')) throw new Denied('Откройте кабинет внутри Telegram');
  const check=fields.filter(x=>x[0]!=='hash').sort((a,b)=>a[0]<b[0]?-1:1).map(([k,v])=>k+'='+v).join('\n');
  if(!await verify(env.TG_WEBAPP_SECRET,hex(hash),check)) throw new Denied('Не удалось проверить вход через Telegram');
  const authDate=Number(p.get('auth_date')); const user=JSON.parse(p.get('user')||'{}');
  if(!Number.isSafeInteger(authDate) || authDate<=0 || authDate>now+30 || now-authDate>3600 || user.is_bot || user.id!==ticket.uid) throw new Denied('Этот кабинет доступен только владельцу. Откройте его через своего бота');
  return ticket;
}
function today(){return new Date(Date.now()+3*3600000).toISOString().slice(0,10);}
function period(day){const y=Number(day.slice(0,4)),m=Number(day.slice(5,7)),d=Number(day.slice(8));return {start:day.slice(0,8)+(d<=15?'01':'16'),end:day.slice(0,8)+(d<=15?'15':String(new Date(Date.UTC(y,m,0)).getUTCDate()))};}
export function selectDay(value){const current=today(); const p=period(current); const next=p.start.endsWith('01')?current.slice(0,8)+'16':new Date(Date.UTC(Number(current.slice(0,4)),Number(current.slice(5,7)),1)).toISOString().slice(0,10); const max=period(next).end; const s=value||current; if(!/^\d{4}-\d{2}-\d{2}$/.test(s) || Number.isNaN(Date.parse(s)) || new Date(s).toISOString().slice(0,10)!==s || s<'2026-09-16' || s>max) throw new Denied('Выберите доступный расчётный период',422);return s;}
async function upstream(path, env, params){if(!env.PRODUCTION_API_KEY && typeof env.PRODUCTION_FETCH!=='function') throw new Denied('Кабинет ещё настраивается',503);const url=new URL(path,API); for(const[k,v]of Object.entries(params||{}))if(v!=null)url.searchParams.set(k,String(v));let r;try{r=await (env.PRODUCTION_FETCH||fetch)(url,{headers:{Authorization:'Bearer '+(env.PRODUCTION_API_KEY||''),Accept:'application/json'},redirect:'error',signal:AbortSignal.timeout(20000)});}catch{throw new Denied('Портал временно не отвечает. Попробуйте обновить позже',503);}if(!r.ok)throw new Denied('Не удалось получить данные с портала',503);const data=await r.json();if(path==='ping'?data.client!=='production-bot':data.source!=='productionwages')throw new Denied('Источник данных не прошёл проверку',503);return data;}
const pick=(o,keys)=>o?Object.fromEntries(keys.filter(k=>Object.hasOwn(o,k)).map(k=>[k,o[k]])):null;
function snapshot(d){return {as_of:d.as_of,period:d.period,postpress:pick(d.postpress,['home_area','areas','point_price','point_price_min','point_price_by_grid','skill_sum','price_since','price_problem']),prepress:pick(d.prepress,['skills','waiting','level','mastered_count','catalog_count','share_percent','point_price','point_price_min','price_since']),digital_print:pick(d.digital_print,['level','salary_by_level','salary_in_payroll','individual_salary']),problems:d.problems||[],generated_at:d.generated_at,data_updated_at:d.data_updated_at};}
